function pick({ hashtags }) {
  if (
    !Array.isArray(hashtags) ||
    !hashtags.length ||
    hashtags.some(
      (x) => typeof x !== "string" || !/^#[\p{L}\p{N}_]+$/u.test(x) || Array.from(x).length > 80,
    )
  )
    throw Error("Configure at least one valid hashtag");
  const hashtag = hashtags[Math.floor(Math.random() * hashtags.length)];
  return { hashtag };
}

return [{ json: pick({ hashtags: ["#techtwitter", "#n8n"] }) }];

function validate({ hashtag, text }) {
  if (typeof hashtag !== "string" || typeof text !== "string") throw Error("Invalid draft");
  const content = text.trim();
  let found = false,
    offset = 0;
  while (offset < content.length) {
    const i = content.indexOf(hashtag, offset);
    if (i < 0) break;
    const next = Array.from(content.slice(i + hashtag.length))[0] || "";
    if (!/[\p{L}\p{N}_]/u.test(next)) {
      found = true;
      break;
    }
    offset = i + hashtag.length;
  }
  if (!content || Array.from(content).length >= 100 || !found)
    throw Error("Draft must include the selected hashtag and be under 100 characters");
  return { hashtag, content, records: [{ fields: { Hashtag: hashtag, Content: content } }] };
}

const result = $input.first().json;
if (result.finish_reason === "length") throw Error("Draft was truncated");
const r = validate({
  hashtag: $("Choose a hashtag").first().json.hashtag,
  text: result.message?.content,
});
return [{ json: { Hashtag: r.hashtag, Content: r.content } }];

const r = $input.first().json;
if (typeof r.id !== "string" || !r.id) throw Error("Airtable did not confirm the draft");
return [{ json: { id: r.id } }];
